<?php
// Quick correctness check for Money
class Money {
    private const SCALE = 40;
    private const OUTPUT_SCALE = 6;
    private string $value;
    private function __construct(string $value) {
        if (!preg_match('/^-?(0|[1-9]\d*)(\.\d+)?$/', $value)) throw new Exception("bad $value");
        $this->value = self::normalize($value);
    }
    public static function of(string $v): self { return new self(trim($v)); }
    public static function zero(): self { return new self('0'); }
    public function value(): string { return $this->value; }
    public function __toString(): string { return $this->value; }
    public function roundHalfUpTo6(): self {
        if (!preg_match('/^(0|[1-9]\d*)(\.\d+)?$|^-(0|[1-9]\d*)(\.\d+)?$/', $this->value)) throw new Exception("bad");
        $negative = str_starts_with($this->value, '-');
        $body = $negative ? substr($this->value, 1) : $this->value;
        [$int, $frac] = array_pad(explode('.', $body, 2), 2, '');
        // 0-based: $frac[5] is the 6th digit. If >= 5, bump up.
        $digit6 = $frac[5] ?? '0';
        // truncate after 6 digits
        $kept = substr($frac, 0, self::OUTPUT_SCALE);
        if (strlen($kept) < self::OUTPUT_SCALE) $kept = str_pad($kept, self::OUTPUT_SCALE, '0');
        if ($digit6 >= '5') {
            $candidate = bcadd($int.'.'.$kept, '0.000001', self::SCALE);
            if ($negative) $candidate = '-'.$candidate;
            return new self($candidate);
        }
        return new self(($negative ? '-' : '').$int.'.'.$kept);
    }
    private static function normalize(string $value): string {
        if (bccomp($value, '0', self::SCALE) === 0) return '0';
        $neg = str_starts_with($value, '-');
        $body = $neg ? substr($value,1) : $value;
        $padded = bcadd($body, '0', self::SCALE);
        $tr = rtrim(rtrim($padded, '0'), '.');
        return ($neg ? '-' : '').$tr;
    }
}
