final class RatingRepository
{
    public function __construct(private readonly EntityManagerInterface $em)
    {
    }

    /** Создаёт или обновляет rated-строку (unique по event_id). */
    public function markRated(int $eventId, int $priceRowId, string $cost): void
    {
        $r = $this->em->getRepository(Rating::class)->findOneBy(['eventId' => $eventId]);
        if ($r !== null) {
            $r->priceRowId = $priceRowId;
            $r->cost = $cost;
            $r->ratedAt = new \DateTimeImmutable();
            return;
        }

        $r = new Rating();
        $r->eventId = $eventId;
        $r->priceRowId = $priceRowId;
        $r->cost = $cost;
        $r->ratedAt = new \DateTimeImmutable();
        $this->em->persist($r);
    }

    /** @return array<string, array{eventId:int, priceRowId:int, cost:string}> eventId (string) => rating */
    public function allRated(): array
    {
        $result = [];
        foreach ($this->em->getRepository(Rating::class)->findAll() as $r) {
            $result[(string) $r->eventId] = [
                'eventId' => $r->eventId,
                'priceRowId' => $r->priceRowId,
                'cost' => $r->cost,
            ];
        }
        return $result;
    }
}
