        ->createQueryBuilder('e')
        ->andWhere('e.id NOT IN (SELECT r.eventId FROM App\Entity\Rating r)')
        ->getQuery()
        ->getResult()
        .filter(fn (UsageEventRow $e) => !in_array((int) $e->id, $ratedIds, true));
}

