        }

        $this->em->flush();

        // Пересчёт: все rated-строки, чей priceRowId в списке затронутых id
        $rater = new Rater($this->providers->allAsArray());

        $touchedIds = $this->em->createQuery(
            'SELECT p.id FROM App\Entity\PriceRow p'
        )
            ->andWhere('p.id IN ('.implode(',', array_column(array_map(fn ($s) => $s, $priceSheets), 'id')).')')
            ->getQuery()
            ->getSingleColumnResult();

        // проще: просто пересчитать ВСЕ rated-строки, т.к. событие может быть расценено любой строкой
        $revised = 0;
        $delta = '0';
        $ratingsToReprice = $this->em->createQuery(
            'SELECT e, r FROM App\Entity\UsageEventRow e JOIN App\Entity\Rating r WITH r.eventId = e.id ORDER BY e.id ASC'
        )->getResult();

        foreach ($ratingsToReprice as [$e, $rating]) {
            $oldCost = $rating->cost;
            $bestRow = $this->prices->findLatestUpTo($e->provider, $e->model, $e->ts);
            if ($bestRow === null) {
                continue;
            }
            $newCost = $rater->costRounded($e, $bestRow);
            $d = bcsub($newCost, $oldCost, 40);
            $delta = bcadd($delta, $d, 40);
            $rating->cost = Money::of($newCost)->value();
            $rating->priceRowId = (int) $bestRow->id;
            $revised++;
        }

        $this->em->flush();

        $output->writeln("REPRICED_EVENTS={$revised}");
        $output->writeln("REPRICE_DELTA_USD=".Money::of($delta)->toFixed6());

        return 0;
    }
}

