edits.newText:
/** @param array<string,string> $env */
private function shell(string $args, array $env, string $cwd): array
{
    // use a temp file for the args to avoid shell-quoting hell
    $argsFile = tempnam(sys_get_temp_dir(), 'args');
    file_put_contents($argsFile, $args);
    $command = sprintf(
        'cd %s && %s /usr/bin/env php bin/console "/$(cat %s)" 2>&1',
        escapeshellarg($cwd),
        $this->envString($env),
        $argsFile
    );
    $output = [];
    exec($command, $output, $rc);
    $joined = implode("\n", $output);
    @unlink($argsFile);

    return [$rc, $joined];
}

