private function shell(string $command): array
{
    $output = [];
    exec($command, $output, $rc);
    $joined = implode("\n", $output);
    // preserve trailing newline(s) — but avoid extra empty lines from exec's buffering
    if (str_ends_with($joined, "\n")) {
        $joined .= "\n";
    }

    return [$rc, $joined];
}

